<?php
include 'includes/cek_session.php';include 'config/koneksi.php';$embed=(($_GET['embed']??'')==='1');
$role=hak_role_efektif();
$sql="SELECT id,tanggal,nama_siswa,(SELECT nis FROM t_siswa WHERE t_siswa.id=t_pelanggaran_siswa.siswa_id) AS nis,nama_kelas,nama_pelanggaran,poin,tindakan,status,nama_guru FROM t_pelanggaran_siswa WHERE status <> 'Selesai'";
if($role===HAK_WALI_KELAS){
 $sql .= " AND EXISTS (SELECT 1 FROM t_wali_kelas wk INNER JOIN t_guru g ON g.id=wk.guru_id WHERE g.user_id=? AND wk.status_aktif=1 AND wk.kelas_id=t_pelanggaran_siswa.kelas_id AND (wk.tahun_ajaran_id=t_pelanggaran_siswa.tahun_ajaran_id OR t_pelanggaran_siswa.tahun_ajaran_id IS NULL))";
 $sql .= " ORDER BY tanggal DESC,id DESC";
 $st=mysqli_prepare($koneksi,$sql); $uid=(int)($_SESSION['id']??0); mysqli_stmt_bind_param($st,'i',$uid); mysqli_stmt_execute($st); $q=mysqli_stmt_get_result($st);
}else{ $sql .= " ORDER BY tanggal DESC,id DESC"; $q=mysqli_query($koneksi,$sql); }
if(!$q)die('Gagal mengambil data: '.htmlspecialchars(mysqli_error($koneksi)));function eT($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}?>
<?php if(!$embed):?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tindakan Pelanggaran</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php endif;?>
<main class="container-fluid p-3 p-md-4 bg-white"><h2 class="fw-bold">Tindakan Pelanggaran</h2><p class="text-secondary">Isi tindak lanjut pembinaan. Data berstatus Selesai otomatis dipindahkan dari daftar tindakan ke riwayat.</p><?php if(!empty($_SESSION['pesan'])):?><div class="alert alert-info alert-dismissible fade show"><?=eT($_SESSION['pesan'])?><button type="button" class="btn-close" data-bs-dismiss="alert"></button></div><?php unset($_SESSION['pesan']);endif;?>
<div class="mb-3"><input type="search" id="cariTindakan" class="form-control" placeholder="Cari siswa berdasarkan NIS/nama, kelas, atau pelanggaran..."></div><div class="table-responsive"><table id="tabelTindakan" class="table table-bordered table-hover align-middle"><thead class="table-light"><tr><th>No</th><th>Tanggal</th><th>Siswa / Kelas</th><th>Pelanggaran</th><th>Poin</th><th>Guru</th><th style="min-width:300px">Tindakan & Status</th><th>Aksi</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($q)):?><tr><td><form id="tindakan<?=(int)$r['id']?>" method="post" action="proses_tindakan.php"></form><input form="tindakan<?=(int)$r['id']?>" type="hidden" name="id" value="<?=(int)$r['id']?>"><input form="tindakan<?=(int)$r['id']?>" type="hidden" name="embed" value="<?=$embed?'1':'0'?>"><?=$no++?></td><td><?=eT($r['tanggal'])?></td><td><strong><?=eT($r['nama_siswa'])?></strong><br><small class="text-muted">NIS: <?=eT($r['nis']??'')?> · <?=eT($r['nama_kelas'])?></small></td><td><?=eT($r['nama_pelanggaran'])?></td><td><span class="badge text-bg-danger"><?=(int)$r['poin']?></span></td><td><?=eT($r['nama_guru'])?></td><td><textarea form="tindakan<?=(int)$r['id']?>" name="tindakan" class="form-control form-control-sm mb-2" rows="2" required placeholder="Isi tindakan pembinaan..."><?=eT($r['tindakan'])?></textarea><select form="tindakan<?=(int)$r['id']?>" name="status" class="form-select form-select-sm"><option value="Belum ditindaklanjuti" <?=$r['status']==='Belum ditindaklanjuti'?'selected':''?>>Belum ditindaklanjuti</option><option value="Dalam proses" <?=$r['status']==='Dalam proses'?'selected':''?>>Dalam proses</option><option value="Selesai" <?=$r['status']==='Selesai'?'selected':''?>>Selesai</option></select></td><td><button form="tindakan<?=(int)$r['id']?>" class="btn btn-sm btn-primary" type="submit">Simpan</button></td></tr><?php endwhile;?><?php if(mysqli_num_rows($q)===0):?><tr><td colspan="8" class="text-center text-muted py-4">Belum ada catatan pelanggaran.</td></tr><?php endif;?></tbody></table></div></main><script>
document.getElementById('cariTindakan')?.addEventListener('input',function(){const k=this.value.toLocaleLowerCase('id');document.querySelectorAll('#tabelTindakan tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLocaleLowerCase('id').includes(k));});
</script><?php if(!$embed):?></body></html><?php endif;?>
